import assert from 'node:assert/strict';
import {randomUUID} from 'node:crypto';
import type {Page} from 'playwright';
import type {PrismaClient} from '@prisma/client';
import {dashboardStorageKey,writeDashboardObject} from '../../src/server/storage';
import {waitForBrowserJson} from './browser-poll';
export async function verifySourceMonitoring(page:Page,origin:string,workspaceId:string,db:PrismaClient,check:(page:Page,phase:string)=>Promise<void>){
 const observationWindow=new Date(Math.floor(Date.now()/60000)*60000),observationScope={kind:'REQUEST',name:'/api/workspaces/[workspaceId]/monitoring',window:{gte:observationWindow}},beforeRequests=(await db.dashboardObservationBucket.aggregate({where:observationScope,_sum:{count:true}}))._sum.count??0;
 const name='Source health '+randomUUID().slice(0,8),root=origin+'/dashboard/app/workspaces/'+workspaceId,api='/dashboard/app/api/workspaces/'+workspaceId;
 const source=await db.dashboardDataSource.create({data:{workspaceId,name,kind:'FILE',status:'CONNECTED'}}),dataset=await db.dashboardDataset.create({data:{workspaceId,sourceId:source.id,name}}),versionId=randomUUID(),bytes=Buffer.from('id,amount\nA,10\nB,20\n'),key=dashboardStorageKey(workspaceId,dataset.id,versionId);
 type State={sourceMonitoring:{incidents:{id:string;sourceId:string;kind:string;status:string;generation:number}[]}};
 const state=()=>waitForBrowserJson<State>(page,api+'/monitoring',r=>r.sourceMonitoring.incidents.some(i=>i.sourceId===source.id&&i.kind==='REFRESH_FAILURE'&&i.status==='OPEN'),'Terminal source failure notification');
 async function upload(csv:string){const previousVersion=(await db.dashboardDataset.findUniqueOrThrow({where:{id:dataset.id}})).activeVersionId;await page.goto(root+'/studio?create=1');await page.getByRole('region',{name:'Choose dashboard type',exact:true}).getByRole('button',{name:/^Sales performance\b/}).click();await page.getByLabel('Upload destination').selectOption(dataset.id);await page.getByLabel('CSV, JSON or Excel file',{exact:true}).setInputFiles({name:'source-health.csv',mimeType:'text/csv',buffer:Buffer.from(csv)});const uploaded=page.waitForResponse(r=>r.request().method()==='POST'&&new URL(r.url()).pathname.endsWith('/datasets/'+dataset.id+'/versions'));await page.getByRole('button',{name:'Upload and profile dataset',exact:true}).click();const response=await uploaded;assert.equal(response.status(),202);await page.getByText('File uploaded and queued for profiling.',{exact:false}).waitFor();await waitForBrowserJson<{datasets:{id:string;status:string;pendingVersionId:string|null;latestVersionId:string|null}[]}>(page,api+'/datasets',r=>r.datasets.some(d=>d.id===dataset.id&&d.status==='READY'&&!d.pendingVersionId&&Boolean(d.latestVersionId)&&d.latestVersionId!==previousVersion),'Source correction profiling');await page.reload();await page.getByRole('region',{name:'Choose dashboard type',exact:true}).getByRole('button',{name:/^Sales performance\b/}).click();await page.getByLabel('Dataset for a new dashboard',{exact:true}).selectOption(dataset.id);}
 async function confirmAndCalculate(){await page.getByText('Review suggested field meanings (not yet confirmed)',{exact:true}).click();for(const [field,concept] of [['id','ORDER'],['amount','REVENUE']])await page.getByLabel('Meaning of '+field,{exact:true}).selectOption(concept);await page.getByRole('button',{name:'Save confirmed field meanings',exact:true}).click();await page.getByText('Field choices saved.',{exact:false}).waitFor();await page.getByText('Confirm business calculation rules',{exact:true}).click();for(const [label,value] of [['What does one row represent?','ORDER'],['Currency structure','SINGLE'],['Revenue basis','NET'],['Cost basis','COGS'],['Refunds already included in revenue?','true'],['Discounts already included in revenue?','true'],['Tax already included in revenue?','false'],['Shipping already included in revenue?','false'],['Cancelled orders','ALREADY_EXCLUDED'],['Returned units','ALREADY_NETTED']])await page.getByLabel(label,{exact:true}).selectOption(value);await page.getByLabel('Three-letter currency code',{exact:true}).fill('USD');await page.getByRole('button',{name:'Save business rules',exact:true}).click();await page.getByText('Business rules saved.',{exact:false}).waitFor();await page.getByRole('button',{name:'Calculate metrics',exact:true}).click();}
 try{
  await page.goto(root+'/monitoring');await writeDashboardObject(key,bytes);await db.dashboardDatasetVersion.create({data:{id:versionId,datasetId:dataset.id,version:1,status:'PENDING',sourceFormat:'CSV',storageKey:key,fileSize:BigInt(bytes.length),checksum:'0'.repeat(64)}});await db.dashboardJob.create({data:{workspaceId,kind:'DATASET_INGEST',attempts:2,payload:{datasetId:dataset.id,versionId,format:'csv'}}});await state();await page.reload();await page.getByRole('navigation',{name:'Workspace navigation',exact:true}).getByRole('status').waitFor();const health=page.getByRole('region',{name:'Source health and notifications',exact:true});await health.getByRole('button',{name:'Acknowledge source incident for '+name,exact:true}).click();await waitForBrowserJson<State>(page,api+'/monitoring',r=>r.sourceMonitoring.incidents.some(i=>i.sourceId===source.id&&i.status==='ACKNOWLEDGED'),'Source incident acknowledgement');await check(page,'customer-source-failure-inbox');
  await upload('id,amount\nA,10\nA,20\n');await confirmAndCalculate();await waitForBrowserJson<State>(page,api+'/monitoring',r=>r.sourceMonitoring.incidents.some(i=>i.sourceId===source.id&&i.kind==='METRIC_FAILURE'&&i.status==='OPEN'),'Blocked metric notification');await page.goto(root+'/monitoring');await health.getByRole('heading',{name:name+' — metric failure',exact:true}).waitFor();await check(page,'customer-metric-failure-inbox');
  await health.getByLabel('Monitored source',{exact:true}).selectOption(source.id);await health.getByLabel('Maximum source age in minutes',{exact:true}).fill('1');await health.getByRole('button',{name:'Save source notifications',exact:true}).click();await page.getByText('Source notification settings saved.',{exact:true}).waitFor();
  await db.dashboardDataSource.update({where:{id:source.id},data:{lastSyncedAt:new Date(Date.now()-120000)}});
  await page.reload();await health.getByLabel('Monitored source',{exact:true}).selectOption(source.id);
  // Saving the explicit policy performs an immediate, serialized evaluation.
  await health.getByRole('button',{name:'Save source notifications',exact:true}).click();await waitForBrowserJson<State>(page,api+'/monitoring',r=>r.sourceMonitoring.incidents.some(i=>i.sourceId===source.id&&i.kind==='STALE_SOURCE'&&i.status==='OPEN'),'Configured stale source notification');await page.getByRole('button',{name:'Refresh monitoring',exact:true}).click();await health.getByRole('heading',{name:name+' — stale source',exact:true}).waitFor();await page.setViewportSize({width:390,height:844});await check(page,'customer-source-notifications-mobile');assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await page.setViewportSize({width:1280,height:900});
  await upload('id,amount\nA,10\nB,20\n');await confirmAndCalculate();await waitForBrowserJson<State>(page,api+'/monitoring',r=>r.sourceMonitoring.incidents.filter(i=>i.sourceId===source.id).every(i=>i.status==='RESOLVED'),'Source/metric recovery');await page.goto(root+'/monitoring');await check(page,'customer-source-notification-recovery');
  const deadline=Date.now()+10000;let count=0;while(Date.now()<deadline){count=(await db.dashboardObservationBucket.aggregate({where:observationScope,_sum:{count:true}}))._sum.count??0;if(count>beforeRequests)break;await new Promise(r=>setTimeout(r,100));}assert.ok(count>beforeRequests,'Real Next HTTP requests must publish route latency/status aggregates');
  console.log('PASS: actual terminal worker failure, customer acknowledgement, blocked metric notification, explicit freshness policy/stale warning, corrected-source recalculation/recovery, real request instrumentation and four desktop/mobile accessibility scans.');
 }catch(error){console.error('Source monitoring fixture state',JSON.stringify({messages:await page.getByRole('status').allTextContents(),alerts:await page.getByRole('alert').allTextContents(),jobs:await db.dashboardJob.findMany({where:{workspaceId,payload:{path:['datasetId'],equals:dataset.id}},orderBy:{createdAt:'desc'},take:5,select:{kind:true,status:true,lastError:true,payload:true,result:true}}),runs:await db.dashboardAnalysisRun.findMany({where:{workspaceId,datasetId:dataset.id},select:{status:true,versionId:true,semanticRevision:true,createdAt:true}})}));throw error;}finally{await page.setViewportSize({width:1280,height:900});await db.dashboardDataset.deleteMany({where:{id:dataset.id,workspaceId}});await db.dashboardDataSource.deleteMany({where:{id:source.id,workspaceId}});}
}
